func(e *testEnv, c *http.Client, sid string) {
		resp := doReq(t, c, "POST", e.srv.URL+"/api/projects/demo/chats/"+sid+"/model",
			`{"model":"модель-next","harness":"codextest"}`)
		if raw := body(t, resp); resp.StatusCode != http.StatusOK {
			t.Fatalf("выбор: %d %s", resp.StatusCode, raw)
		}
}

func(e *testEnv, c *http.Client, sid string) {
		resp := doReq(t, c, "POST", e.srv.URL+"/api/projects/demo/chats/"+sid+"/model",
			`{"model":"gpt-6.2-sol","harness":"codextest"}`)
		if raw := body(t, resp); resp.StatusCode != http.StatusOK {
			t.Fatalf("выбор: %d %s", resp.StatusCode, raw)
		}
}

func(e *testEnv, _ *http.Client, sid string) {
				if err := e.s.chatStoreUpdate(sid, func(st chatStore) chatStore {
					st.CxModel = "прежняя-модель"
					return st
				}); err != nil {
					t.Fatal(err)
				}
				out, err := exec.Command(node, "testdata/apptask_model_browser.mjs",
					e.srv.URL, chrome, e.cfg.Token, sid, mode).CombinedOutput()
				if err != nil {
					t.Fatalf("меню рабочего чата: %v\n%s", err, out)
				}
				t.Log(string(out))
}

func(previous chatStore) chatStore {
		st.ProposalContexts = mergeProposalContexts(previous.ProposalContexts, st.ProposalContexts)
		st.SelectionContexts = mergeSelectionContexts(previous.SelectionContexts, st.SelectionContexts)
		if !strings.HasPrefix(key, "tmux-") && st.GroomSource == "" {
			st.GroomSource, st.GroomMode, st.GroomTree = previous.GroomSource, previous.GroomMode, previous.GroomTree
		}
		return st
	}

